@Override
public void checkResourceFolder(@NonNull ResourceContext context, @NonNull File folder) {
    ResourceFolderType folderType = ResourceFolderType.getType(folder.getName());
    if (folderType == null) return;
    String density = getDensityQualifier(folder.getName());
    boolean densitySpecific = density != null && DENSITY_QUALIFIERS.contains(density);
    for (File file : folder.listFiles()) {
        if (file.isFile() && isImageFile(file)) {
            String baseName = getBaseName(file.getName());
            String key = folderType.getName() + "/" + baseName;
            IconEntry entry = mIcons.get(key);
            if (entry == null) {
                entry = new IconEntry(folderType, baseName);
                mIcons.put(key, entry);
            }
            entry.files.add(file);
            if (densitySpecific) {
                entry.foundDensities.add(density);
            }
        }
    }
}
```
